answer.sql:
SELECT 100.0 * SUM(CASE WHEN p.gender = 'F' THEN 1 ELSE 0 END) / COUNT(*) AS female_percentage
FROM (SELECT DISTINCT PATIENT FROM medications WHERE DESCRIPTION = 'Penicillin V Potassium 250 MG') AS m
JOIN patients AS p ON p.patient = m.PATIENT;

