SELECT 100.0 * COUNT(DISTINCT c.PATIENT) / COUNT(DISTINCT p.patient) AS "PREVALENCE PERCENTAGE"
FROM patients AS p
LEFT JOIN conditions AS c ON c.PATIENT = p.patient AND c.CODE = 64859006;

SELECT COUNT(DISTINCT p.patient) AS total_patients, COUNT(DISTINCT p.deathdate) AS deceased_patients, COUNT(DISTINCT c.PATIENT) AS condition_patients
FROM patients AS p
LEFT JOIN conditions AS c ON c.PATIENT = p.patient AND c.CODE = 64859006;

